function validate([team, dist]) {
  if (!Array.isArray(team) || team.length < 1 || team.length > 100000) return 'team needs 1 to 100000 entries.';
  if (team.some(v => v !== 0 && v !== 1)) return 'Each entry of team is 0 or 1.';
  if (!Number.isInteger(dist) || dist < 1 || dist > team.length) return 'dist must be between 1 and team.length.';
  return null;
}

