function catchMaximumAmountofPeople(team, dist) {
  const n = team.length;
  let caught = 0;
  let target = 0;
  for (let i = 0; i < n; i++) {
    if (team[i] !== 1) {
      continue;
    }
    while (target < n && (team[target] !== 0 || target < i - dist)) {
      target++;
    }
    if (target < n && target <= i + dist) {
      caught++;
      target++;
    }
  }
  return caught;
}

