function catchMaximumAmountofPeople(team, dist) {
  // Maximum bipartite matching (augmenting paths) between catchers and runners.
  const owner = new Array(team.length).fill(-1);
  const tryCatch = (i, visited) => {
    for (let j = Math.max(0, i - dist); j <= Math.min(team.length - 1, i + dist); j++) {
      if (team[j] !== 0 || visited.has(j)) continue;
      visited.add(j);
      if (owner[j] === -1 || tryCatch(owner[j], visited)) {
        owner[j] = i;
        return true;
      }
    }
    return false;
  };
  let total = 0;
  for (let i = 0; i < team.length; i++) if (team[i] === 1 && tryCatch(i, new Set())) total++;
  return total;
}

