function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 12);
  const density = [0.1, 0.3, 0.5, 0.7, 0.9][Math.floor(rand() * 5)];
  const team = [];
  if (size === 'large' && rand() < 0.3) {
    // Long blocks of catchers and runners stress the pointer that skips ahead.
    while (team.length < n) {
      const value = team.length === 0 ? Math.floor(rand() * 2) : 1 - team[team.length - 1];
      const block = 1 + Math.floor(rand() * 200);
      for (let k = 0; k < block && team.length < n; k++) team.push(value);
    }
  } else {
    for (let k = 0; k < n; k++) team.push(rand() < density ? 1 : 0);
  }
  const dist = rand() < 0.6 ? 1 + Math.floor(rand() * Math.min(n, 5)) : 1 + Math.floor(rand() * n);
  return [team, dist];
}
